import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const timelines = [];
  const entries = [
    { label: 'HOME', key: 'home', active: true },
    { label: 'FEATURES', key: 'features', active: false },
    { label: 'COLLECTION', key: 'collection', active: false },
    { label: 'PRICING', key: 'pricing', active: false },
    { label: 'JOURNAL', key: 'journal', active: false }
  ];

  const colors = {
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
    inactive: new THREE.Color('#a6adba')
  };

  // Create gradient texture for rail (vertical #1b1b23 -> #101015)
  const gradientData = new Uint8Array(4 * 256);
  const topColor = new THREE.Color('#1b1b23');
  const bottomColor = new THREE.Color('#101015');

  for (let i = 0; i < 256; i++) {
    const t = i / 255;
    const color = new THREE.Color().lerpColors(topColor, bottomColor, t);
    const idx = i * 4;
    gradientData[idx] = Math.round(color.r * 255);
    gradientData[idx + 1] = Math.round(color.g * 255);
    gradientData[idx + 2] = Math.round(color.b * 255);
    gradientData[idx + 3] = 255;
  }

  const gradientTexture = new THREE.DataTexture(gradientData, 1, 256, THREE.RGBAFormat);
  gradientTexture.needsUpdate = true;

  // Main container
  const dock = new THREE.Group();
  dock.position.y = 0.4;

  // Rail mesh (3.6w x 0.5h at z=0.15)
  const railGeometry = new THREE.PlaneGeometry(3.6, 0.5);
  const railMaterial = new THREE.MeshStandardMaterial({
    map: gradientTexture,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    anisotropy: 0.6
  });
  const railMesh = new THREE.Mesh(railGeometry, railMaterial);
  railMesh.position.z = 0.15;
  dock.add(railMesh);

  // Contact shadow plane (35% opacity, offset 0.06 down)
  const shadowGeometry = new THREE.PlaneGeometry(3.8, 0.6);
  const shadowMaterial = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35
  });
  const shadowMesh = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.position.set(0, -0.06, 0);
  dock.add(shadowMesh);

  // Create entries
  const entryObjects = [];
  let activeIndex = 0;

  entries.forEach((entry, index) => {
    const entryGroup = new THREE.Group();
    entryGroup.position.set((index - 2) * 0.68, 0, 0.16);

    // Hit cell (0.6w x 0.34h, invisible)
    const cellGeo = new THREE.PlaneGeometry(0.6, 0.34);
    const cellMat = new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 0
    });
    const cellMesh = new THREE.Mesh(cellGeo, cellMat);
    cellMesh.position.z = 0.01;
    entryGroup.add(cellMesh);

    // Text
    const textGroup = new THREE.Group();
    textGroup.position.z = 0.02;

    const textMesh = ctx.fontAtlas.createTextMesh(entry.label, {
      fontSize: 13,
      fontFamily: 'JetBrains Mono',
      fontWeight: entry.active ? 700 : 400,
      letterSpacing: 0.08,
      color: entry.active ? colors.paper : colors.inactive,
      lineHeight: 1
    });

    if (textMesh) {
      const bbox = new THREE.Box3().setFromObject(textMesh);
      const width = bbox.max.x - bbox.min.x;
      textMesh.position.x = -width / 2;
      textMesh.position.y = 0;
      textGroup.add(textMesh);
    }
    entryGroup.add(textGroup);

    // Underline bar (active only, 0.28w x 0.025h)
    let underlineBar = null;
    if (entry.active) {
      const underlineGeo = new THREE.PlaneGeometry(0.28, 0.025);
      const underlineMat = new THREE.MeshBasicMaterial({
        color: 0xff2a38,
        emissive: 0xff2a38,
        emissiveIntensity: 1.8
      });
      underlineBar = new THREE.Mesh(underlineGeo, underlineMat);
      underlineBar.position.set(0, -0.12, 0.02);
      entryGroup.add(underlineBar);
    }

    entryGroup.userData = {
      key: entry.key,
      index: index,
      isActive: entry.active,
      cellMesh,
      textMesh,
      textGroup,
      underlineBar,
      colorLerp: 0,
      handlers: {
        onMouseEnter: null,
        onMouseLeave: null,
        onMouseDown: null,
        onMouseUp: null
      }
    };

    entryObjects.push(entryGroup);
    dock.add(entryGroup);

    if (entry.active) {
      activeIndex = index;
    }
  });

  // Interaction handlers
  entryObjects.forEach((entryGroup) => {
    const data = entryGroup.userData;

    data.handlers.onMouseEnter = () => {
      if (data.isActive) return;
      gsap.killTweensOf(data);
      gsap.to(data, {
        colorLerp: 1,
        duration: 0.16,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        onUpdate: () => {
          if (data.textMesh?.material?.color) {
            const c = new THREE.Color().lerpColors(
              colors.inactive,
              colors.paper,
              data.colorLerp
            );
            data.textMesh.material.color.copy(c);
          }
        }
      });
    };

    data.handlers.onMouseLeave = () => {
      if (data.isActive) return;
      gsap.killTweensOf(data);
      gsap.to(data, {
        colorLerp: 0,
        duration: 0.16,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        onUpdate: () => {
          if (data.textMesh?.material?.color) {
            data.textMesh.material.color.copy(colors.inactive);
          }
        }
      });
    };

    data.handlers.onMouseDown = () => {
      gsap.killTweensOf(data.cellMesh.scale);
      gsap.killTweensOf(data.cellMesh.position);
      gsap.to(data.cellMesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      });
      gsap.to(data.cellMesh.position, {
        z: -0.03,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      });
    };

    data.handlers.onMouseUp = () => {
      gsap.killTweensOf(data.cellMesh.scale);
      gsap.killTweensOf(data.cellMesh.position);
      gsap.to(data.cellMesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      });
      gsap.to(data.cellMesh.position, {
        z: 0.01,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      });
      if (!data.isActive) {
        setActiveEntry(data.index);
      }
    };
  });

  function setActiveEntry(newIndex) {
    if (activeIndex === newIndex) return;

    const oldData = entryObjects[activeIndex].userData;
    const newData = entryObjects[newIndex].userData;

    oldData.isActive = false;
    newData.isActive = true;

    if (oldData.textMesh?.material?.color) {
      oldData.textMesh.material.color.copy(colors.inactive);
    }
    if (newData.textMesh?.material?.color) {
      newData.textMesh.material.color.copy(colors.paper);
    }

    // Remove old underline
    if (oldData.underlineBar) {
      entryObjects[activeIndex].remove(oldData.underlineBar);
      oldData.underlineBar.geometry.dispose();
      oldData.underlineBar.material.dispose();
      oldData.underlineBar = null;
    }

    // Create new underline at old position
    const underlineGeo = new THREE.PlaneGeometry(0.28, 0.025);
    const underlineMat = new THREE.MeshBasicMaterial({
      color: 0xff2a38,
      emissive: 0xff2a38,
      emissiveIntensity: 1.8
    });
    newData.underlineBar = new THREE.Mesh(underlineGeo, underlineMat);
    newData.underlineBar.position.set(0, -0.12, 0.02);

    const oldXPos = (activeIndex - 2) * 0.68;
    const newXPos = (newIndex - 2) * 0.68;
    newData.underlineBar.position.x = oldXPos - newXPos;

    entryObjects[newIndex].add(newData.underlineBar);

    // Animate underline slide with overshoot settle
    const tl = gsap.timeline();
    timelines.push(tl);

    tl.to(newData.underlineBar.position, {
      x: 0,
      duration: 0.26,
      ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)'
    }, 0);

    gsap.fromTo(
      newData.underlineBar.scale,
      { y: 1.04 },
      {
        y: 1.0,
        duration: 0.9,
        ease: 'power4.out',
        delay: 0.26
      }
    );

    activeIndex = newIndex;
  }

  // Mount animation: rise-in (y +0.4 -> 0)
  gsap.from(dock.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)'
  });

  // Cleanup function
  dock.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    gsap.globalTimeline.clear();

    entryObjects.forEach(entry => {
      const data = entry.userData;
      data.cellMesh?.geometry?.dispose();
      data.cellMesh?.material?.dispose();
      data.underlineBar?.geometry?.dispose();
      data.underlineBar?.material?.dispose();
      data.textGroup?.children?.forEach(child => {
        child.geometry?.dispose();
        child.material?.dispose();
      });
    });

    railGeometry.dispose();
    railMaterial.dispose();
    shadowGeometry.dispose();
    shadowMaterial.dispose();
    gradientTexture.dispose();
  };

  return dock;
}
